import json,hashlib
p='/workspace/scratch/volume4/batch469-478.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(475,[
('فأي آية وبرهان ودليل أحسن من آيات الأنبياء وبراهينهم وأدلتهم؟ وهي شهادة من الله سبحانه لهم، بينها لعباده غاية البيان وأظهرها لهم غاية الإظهار بقوله وفعله.', 'Какое знамение, довод и доказательство могут быть прекраснее знамений, доводов и доказательств пророков? Это свидетельство Пречистого Аллаха о них: Он с предельной ясностью разъяснил его Своим рабам и со всей явностью обнаружил его словом и действием.'),
('وفي «الصحيح» عنه صلى الله عليه وسلم أنه قال: «ما من نبي من الأنبياء إلا وقد أوتي من الآيات ما آمن على مثله البشر، وإنما كان الذي أوتيته وحيا أوحاه الله إلي، فأرجو أن أكون أكثرهم تابعا يوم القيامة».', 'В «Сахихе» переданы его слова, да благословит его Аллах и приветствует: «Каждому из пророков были даны такие знамения, при виде которых люди уверовали. Мне же было дано откровение, которое внушил мне Аллах, и я надеюсь, что в День воскресения у меня будет больше последователей, чем у них».'),
('ومن أسمائه تعالى: «المؤمن»، وهو في أحد التفسيرين: المصدق الذي يصدق الصادقين بما يقيم لهم من شواهد صدقهم. فهو الذي صدق رسله وأنبياءه فيما بلغوا عنه، وشهد لهم بأنهم صادقون بالدلائل التي دل بها على صدقهم قضاء وخلقا. فإنه سبحانه أخبر ـ وخبره الصدق، وقوله الحق ـ أنه لا بد أن يري العباد من الآيات الأفقية والنفسية ما يبين لهم أن الوحي الذي بلغته رسله حق، فقال تعالى: {سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق} أي القرآن، فإنه هو المتقدم في قوله: {قل أرأيتم إن كان من عند الله} [فصلت: ٥٢]. ثم قال: {أولم يكف بربك أنه على كل شيء شهيد} [فصلت: ٥٣]. فشهد سبحانه لرسوله بقوله: أن ما جاء به حق، ووعده أن يري العباد من آياته الفعلية الخلقية ما يشهد بذلك أيضا. ثم ذكر ما هو أعظم من ذلك وأجل، وهو شهادته سبحانه على كل شيء، فإن', 'Среди Его имён, Всевышнего, — «Подтверждающий истину» (аль-Му’мин). Согласно одному из двух толкований, это Тот, Кто подтверждает правдивость правдивых, устанавливая свидетельства их правдивости. Он подтвердил правдивость Своих посланников и пророков в переданном ими от Него и засвидетельствовал, что они правдивы, посредством указаний, которыми показал их правдивость в Своих решениях и творении. Пречистый сообщил — а Его весть правдива и Его слово истинно, — что непременно покажет рабам знамения во внешнем мире и в них самих, которые разъяснят им истинность откровения, переданного Его посланниками. Всевышний сказал: {سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق} — «Мы покажем им Наши знамения по краям земли и в них самих, пока им не станет ясно, что это — истина», — то есть Коран, поскольку о нём говорилось выше в словах: {قل أرأيتم إن كان من عند الله} — «Скажи: “Как вы думаете, если это — от Аллаха…”» [41:52]. Затем Он сказал: {أولم يكف بربك أنه على كل شيء شهيد} — «Разве недостаточно того, что твой Господь — Свидетель всякой вещи?» [41:53]. Пречистый Своим словом засвидетельствовал Своему Посланнику, что принесённое им — истина, и обещал ему показать рабам Свои знамения действия и творения, также свидетельствующие об этом. Затем Он упомянул нечто ещё более великое и возвышенное — Своё свидетельство обо всём. Ведь')])
page(476,[
('من أسمائه «الشهيد» الذي لا يغيب عنه شيء، ولا يعزب عنه، بل هو مطلع على كل شيء مشاهد له، عليم بتفاصيله. وهذا استدلال بأسمائه وصفاته، والأول استدلال بقوله وكلماته، والاستدلال بالآيات الأفقية والنفسية استدلال بأفعاله ومخلوقاته.', 'среди Его имён — «Свидетель», от Которого ничто не скрыто и не ускользает: Он осведомлён обо всём, всё созерцает и знает во всех подробностях. Это доказательство посредством Его имён и качеств; первое — посредством Его речи и слов, а доказательство посредством знамений во внешнем мире и в самих людях — посредством Его действий и творений.'),
('فإن قلت: قد فهمت الاستدلال بكلماته والاستدلال بمخلوقاته، فبين لي كيفية الاستدلال بأسمائه وصفاته، فإن ذلك أمر لا عهد لنا به في تخاطبنا ولا في كتبنا.', 'Если ты скажешь: «Я понял доказательство посредством Его слов и посредством Его творений. Разъясни же мне, как доказывают посредством Его имён и качеств, ведь с таким мы не встречаемся ни в наших беседах, ни в наших книгах».'),
('قلت: أجل! وهو لعمر الله كما ذكرت، وشأنه أجل وأعلى، فإن الرب تعالى هو المدلول عليه، وآياته هي الدليل والبرهان.', 'Я отвечу: «Да, клянусь жизнью Аллаха, это так, как ты сказал. И значение этого ещё величественнее и выше, ибо Всевышний Господь — Тот, на Кого указывают, а Его знамения — доказательство и довод».'),
('فاعلم أن الله سبحانه في الحقيقة هو الدال على نفسه بآياته، فهو الدليل لعباده في الحقيقة بما نصبه لهم من الدلالات والآيات. وقد أودع في الفطر التي لم تتنجس بالتعطيل والجحود أنه سبحانه الكامل في أسمائه وصفاته، وأنه الموصوف بكل كمال، المنزه عن كل عيب ونقص. فالكمال كله والجلال والجمال والبهاء والعز والعظمة والكبرياء = كله من لوازم ذاته، يستحيل أن يكون على غير ذلك. فالحياة كلها له، والعلم كله له، والقدرة كلها له، والسمع والبصر والإرادة والمشيئة والرحمة والغنى والجود', 'Знай: в действительности Пречистый Аллах Сам указывает на Себя Своими знамениями. Именно Он направляет Своих рабов установленными для них указаниями и знамениями. Он вложил в естество, не осквернённое отрицанием качеств и непризнанием, то, что Пречистый совершенен в Своих именах и качествах, описан всяким совершенством и пречист от всякого изъяна и недостатка. Всё совершенство, величие, красота, сияние, могущество, величавость и величавое превосходство неотделимы от Его Сущности: невозможно, чтобы Он был иным. Вся жизнь принадлежит Ему, всё знание принадлежит Ему, всё могущество принадлежит Ему; слух, зрение, воля, желание, милость, самодостаточность, щедрость')])
page(477,[
('والإحسان والبر = كله خاص له قائم به، وما خفي عن الخلق من كماله أعظم وأعظم مما عرفوه منه، بل لا نسبة لما عرفوه من ذلك إلى ما لم يعرفوه!', 'благодеяние и благость — всё принадлежит Ему одному и присуще Ему. Скрытое от творений из Его совершенства неизмеримо больше того, что они познали. Более того, познанное ими из этого несоизмеримо с тем, чего они не познали!'),
('ومن كماله المقدس: اطلاعه على كل شيء وشهادته عليه، بحيث لا يغيب عنه وجه من وجوه تفاصيله، ولا ذرة من ذراته باطنا وظاهرا. ومن هذا شأنه، كيف يليق بالعباد أن يشركوا به، وأن يعبدوا معه غيره ويجعلوا معه إلها آخر؟ وكيف يليق بكماله أن يقر من يكذب عليه أعظم الكذب ويخبر عنه بخلاف ما الأمر عليه، ثم ينصره على ذلك ويؤيده، ويعلي كلمته، ويرفع شأنه، ويجيب دعوته، ويهلك عدوه، ويظهر على يديه من الآيات والبراهين والأدلة ما يعجز عن مثله قوى البشر، وهو مع ذلك كاذب عليه مفتر، ساع في الأرض بالفساد؟', 'К Его священному совершенству относится осведомлённость обо всём и свидетельство обо всём: от Него не скрыта ни одна сторона подробностей вещи и ни одна её частица — ни внутренне, ни внешне. Если Он таков, разве подобает рабам приобщать к Нему сотоварищей, поклоняться наряду с Ним иному и признавать наряду с Ним другого бога? Разве совместимо с Его совершенством терпеть того, кто возводит на Него величайшую ложь и сообщает о Нём нечто, противоречащее действительности, а затем помогать ему в этом и поддерживать его, возвышать его слово и положение, отвечать на его мольбу, губить его врага, являть через него такие знамения, доводы и доказательства, какие человеческим силам не под силу, хотя тот — лжец, клевещущий на Него и распространяющий порчу на земле?'),
('ومعلوم أن شهادته سبحانه على كل شيء، وقدرته على كل شيء، وحكمته وعزته وكماله المقدس = يأبى ذلك كل الإباء. ومن ظن ذلك به وجوزه عليه، فهو من أبعد الخلق عن معرفته، وإن عرف منه بعض صفاته كصفة القدرة وصفة المشيئة.', 'Известно, что Его свидетельство обо всём, могущество над всем, мудрость, величие и священное совершенство решительно исключают такое. Тот, кто думает о Нём подобное и допускает это в отношении Него, — один из самых далёких от Его познания, даже если он знает некоторые из Его качеств, такие как могущество и желание.'),
('والقرآن مملوء من هذه الطريق، وهي طريق الخاصة، بل خاصة الخاصة الذين يستدلون بالله على أفعاله، وما يليق به أن يفعله وما لا يفعله.', 'Коран полон такого пути доказательства. Это путь избранных, более того — избраннейших из избранных, которые на основании Аллаха заключают о Его действиях: что Ему подобает совершать и чего Он не совершает.')])
page(478,[
('وإذا تدبرت القرآن رأيته ينادي على ذلك، ويبديه ويعيده لمن له فهم وقلب واع عن الله. قال تعالى: {ولو تقول علينا بعض الأقاويل لأخذنا منه باليمين ثم لقطعنا منه الوتين فما منكم من أحد عنه حاجزين} [الحاقة: ٤٤ ـ ٤٧]. أفلا تراه سبحانه يخبر أن كماله وحكمته وقدرته تأبى أن يقر من تقول عليه بعض الأقاويل، بل لا بد أن يجعله عبرة لعباده، كما جرت بذلك سنته في المتقولين عليه.', 'Если ты вдумываешься в Коран, то видишь, что он возвещает об этом, снова и снова разъясняя это обладающему пониманием и сердцем, внимающим Аллаху. Всевышний сказал: {ولو تقول علينا بعض الأقاويل لأخذنا منه باليمين ثم لقطعنا منه الوتين فما منكم من أحد عنه حاجزين} — «Если бы он приписал Нам некоторые слова, Мы схватили бы его за правую руку, затем перерезали бы ему сердечную артерию, и никто из вас не смог бы его защитить» [69:44–47]. Разве ты не видишь, как Пречистый сообщает, что Его совершенство, мудрость и могущество не допускают терпеть того, кто приписывает Ему некоторые выдуманные слова? Он непременно сделает его назиданием для рабов, каков установленный Им порядок в отношении возводящих на Него ложь.'),
('وقال تعالى: {أم يقولون افترى على الله كذبا فإن يشأ الله يختم على قلبك} [الشورى: ٢٤]. هاهنا انتهى جواب الشرط، ثم أخبر خبرا جازما غير معلق أنه يمحو الباطل ويحق الحق.', 'Всевышний сказал: {أم يقولون افترى على الله كذبا فإن يشأ الله يختم على قلبك} — «Или они говорят: “Он возвёл ложь на Аллаха”? Если Аллах пожелает, Он запечатает твоё сердце» [42:24]. Здесь заканчивается следствие условия. Затем Он сообщил твёрдое, ничем не обусловленное утверждение, что Он стирает ложное и утверждает истину.'),
('قال تعالى: {وما قدروا الله حق قدره إذ قالوا ما أنزل الله على بشر من شيء} [الأنعام: ٩١]، فأخبر أن من نفى عنه الإرسال والكلام لم يقدره حق قدره، ولا عزه كما ينبغي، ولا عظمه كما يستحق؛ فكيف من ظن أنه ينصر الكاذب المفتري عليه ويؤيده، ويظهر على يديه الآيات والأدلة؟', 'Всевышний сказал: {وما قدروا الله حق قدره إذ قالوا ما أنزل الله على بشر من شيء} — «Они не оценили Аллаха должным образом, когда сказали: “Аллах ничего не ниспосылал человеку”» [6:91]. Он сообщил, что отрицающий за Ним отправление посланников и речь не оценил Его должным образом, не признал Его величия как подобает и не возвеличил Его как Он достоин. Что же сказать о думающем, будто Он помогает лжецу, клевещущему на Него, поддерживает его и являет через него знамения и доказательства?'),
('وهذا في القرآن كثير جدا: يستدل بكماله المقدس وأوصافه وجلاله على صدق رسله وعلى وعده ووعيده، ويدعو عباده إلى ذلك، كما يستدل بأسمائه وصفاته على وحدانيته على بطلان الشرك، كما في قوله: {هو الله الذي لا إله إلا هو عالم الغيب والشهادة هو الرحمن الرحيم هو الله الذي لا إله إلا هو الملك القدوس السلام المؤمن المهيمن العزيز الجبار المتكبر سبحان الله عما يشركون} [الحشر: ٢٢ ـ ٢٣]. وأضعاف أضعاف ذلك في القرآن.', 'В Коране это встречается очень часто: на основании Своего священного совершенства, качеств и величия Он доказывает правдивость Своих посланников, Своего обещания и угрозы и призывает рабов к такому доказательству. Так же на основании Своих имён и качеств Он доказывает Свою единственность и несостоятельность многобожия, как в словах: {هو الله الذي لا إله إلا هو عالم الغيب والشهادة هو الرحمن الرحيم هو الله الذي لا إله إلا هو الملك القدوس السلام المؤمن المهيمن العزيز الجبار المتكبر سبحان الله عما يشركون} — «Он — Аллах, нет божества, кроме Него, Знающий сокровенное и явное, Милостивый, Милосердный. Он — Аллах, нет божества, кроме Него, Царь, Пречистый, Безупречный, Подтверждающий истину, Хранитель, Могущественный, Всеподчиняющий, Превознесённый. Пречист Аллах и превыше того, что они приобщают к Нему!» [59:22–23]. И во много, много раз больше этого — в Коране.')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
